//! Read-only table metadata and SQL generated by the visual filter.
use anyhow::{Result, ensure};
use serde::Deserialize;

use crate::sql::{QueryResult, SqlPool};
use crate::store::Kind;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TableMetadata {
    Indexes,
    ForeignKeys,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TableFilter {
    pub match_any: bool,
    pub conditions: Vec<Condition>,
}

#[derive(Deserialize)]
pub struct Condition {
    pub column: String,
    pub operator: Operator,
    pub value: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Operator {
    Equals,
    NotEquals,
    Greater,
    Less,
    Contains,
    IsNull,
    IsNotNull,
}

impl SqlPool {
    pub fn visual_predicate(&self, filter: TableFilter) -> Result<String> {
        ensure!(filter.conditions.len() <= 20, "Too many filter conditions");
        let clauses = filter
            .conditions
            .into_iter()
            .map(|condition| {
                ensure!(
                    !condition.column.is_empty()
                        && !condition.column.contains('\0')
                        && !condition.value.contains('\0'),
                    "Invalid filter condition"
                );
                let column = self.quote_ident(&condition.column);
                let value = |v: &str| self.quote_lit(v);
                let clause = match condition.operator {
                    Operator::IsNull => format!("{column} IS NULL"),
                    Operator::IsNotNull => format!("{column} IS NOT NULL"),
                    Operator::Contains => {
                        let escaped = condition
                            .value
                            .replace('!', "!!")
                            .replace('%', "!%")
                            .replace('_', "!_");
                        let cast = if self.dialect() == Kind::Mysql {
                            "CHAR"
                        } else {
                            "TEXT"
                        };
                        format!(
                            "CAST({column} AS {cast}) LIKE {} ESCAPE '!'",
                            value(&format!("%{escaped}%"))
                        )
                    }
                    operator => {
                        let op = match operator {
                            Operator::Equals => "=",
                            Operator::NotEquals => "<>",
                            Operator::Greater => ">",
                            Operator::Less => "<",
                            _ => unreachable!(),
                        };
                        format!("{column} {op} {}", value(&condition.value))
                    }
                };
                Ok(clause)
            })
            .collect::<Result<Vec<_>>>()?;
        Ok(clauses.join(if filter.match_any { " OR " } else { " AND " }))
    }

    pub async fn metadata(
        &self,
        schema: &str,
        table: &str,
        kind: TableMetadata,
    ) -> Result<QueryResult> {
        let (s, t) = (self.quote_lit(schema), self.quote_lit(table));
        let (sql, columns): (String, &[&str]) = match (self.dialect(), kind) {
            (Kind::Mysql, TableMetadata::Indexes) => (format!(
                "SELECT INDEX_NAME, SEQ_IN_INDEX, COLUMN_NAME, NON_UNIQUE = 0, INDEX_TYPE
                 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = {s} AND TABLE_NAME = {t}
                 ORDER BY INDEX_NAME, SEQ_IN_INDEX"
            ), &["index", "position", "column", "unique", "type"]),
            (Kind::Mysql, TableMetadata::ForeignKeys) => (format!(
                "SELECT k.CONSTRAINT_NAME, k.ORDINAL_POSITION, k.COLUMN_NAME, k.REFERENCED_TABLE_SCHEMA,
                        k.REFERENCED_TABLE_NAME, k.REFERENCED_COLUMN_NAME, r.UPDATE_RULE, r.DELETE_RULE
                 FROM information_schema.KEY_COLUMN_USAGE k
                 JOIN information_schema.REFERENTIAL_CONSTRAINTS r
                   ON r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME
                   AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME
                 WHERE k.TABLE_SCHEMA = {s} AND k.TABLE_NAME = {t} AND k.REFERENCED_TABLE_NAME IS NOT NULL
                 ORDER BY k.CONSTRAINT_NAME, k.ORDINAL_POSITION"
            ), &["constraint", "position", "column", "referenced schema", "referenced table", "referenced column", "on update", "on delete"]),
            (Kind::Postgres, TableMetadata::Indexes) => (format!(
                "SELECT i.relname, x.indisunique, x.indisprimary, x.indisvalid, pg_catalog.pg_get_indexdef(i.oid)
                 FROM pg_catalog.pg_index x
                 JOIN pg_catalog.pg_class i ON i.oid = x.indexrelid
                 JOIN pg_catalog.pg_class c ON c.oid = x.indrelid
                 JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                 WHERE n.nspname = {s} AND c.relname = {t} ORDER BY i.relname"
            ), &["index", "unique", "primary", "valid", "definition"]),
            (Kind::Postgres, TableMetadata::ForeignKeys) => (format!(
                "SELECT f.conname, rn.nspname, r.relname, pg_catalog.pg_get_constraintdef(f.oid)
                 FROM pg_catalog.pg_constraint f
                 JOIN pg_catalog.pg_class c ON c.oid = f.conrelid
                 JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                 JOIN pg_catalog.pg_class r ON r.oid = f.confrelid
                 JOIN pg_catalog.pg_namespace rn ON rn.oid = r.relnamespace
                 WHERE n.nspname = {s} AND c.relname = {t} AND f.contype = 'f' ORDER BY f.conname"
            ), &["constraint", "referenced schema", "referenced table", "definition"]),
            (Kind::Sqlite, TableMetadata::Indexes) => {
                return self.sqlite_indexes(schema, table).await;
            }
            (Kind::Sqlite, TableMetadata::ForeignKeys) => (
                self.pragma(schema, table, "foreign_key_list"),
                &["constraint", "position", "referenced table", "column", "referenced column", "on update", "on delete", "match"],
            ),
            _ => unreachable!(),
        };
        let mut result = self
            .execute(sql)
            .await?
            .into_iter()
            .next()
            .unwrap_or_default();
        if result.columns.is_empty() || result.columns.len() == columns.len() {
            result.columns = columns.iter().map(|name| name.to_string()).collect();
        }
        Ok(result)
    }

    fn pragma(&self, schema: &str, object: &str, name: &str) -> String {
        let scope = if matches!(self, Self::D1(_)) {
            String::new()
        } else {
            format!("{}.", self.quote_ident(schema))
        };
        format!("PRAGMA {scope}{name}({})", self.quote_lit(object))
    }

    async fn sqlite_indexes(&self, schema: &str, table: &str) -> Result<QueryResult> {
        let scope = if matches!(self, Self::D1(_)) {
            String::new()
        } else {
            format!("{}.", self.quote_ident(schema))
        };
        let table_literal = self.quote_lit(table);
        // sqlite_master works in both SQLite and D1. The PRAGMA supplies autoindexes
        // and uniqueness; SQL text supplies the key expressions and partial predicate.
        let sql = format!(
            "SELECT name, sql FROM {scope}sqlite_master WHERE type = 'index' AND tbl_name = {table_literal}"
        );
        let definitions = self
            .execute(sql)
            .await?
            .into_iter()
            .next()
            .unwrap_or_default();
        let mut indexes = self
            .execute(self.pragma(schema, table, "index_list"))
            .await?
            .into_iter()
            .next()
            .unwrap_or_default();
        if indexes.columns.is_empty() {
            indexes.columns = ["seq", "name", "unique", "origin", "partial"]
                .map(String::from)
                .to_vec();
        }
        let name_index = indexes.columns.iter().position(|name| name == "name");
        let queries = indexes
            .rows
            .iter()
            .filter_map(|row| {
                name_index
                    .and_then(|i| row.get(i)?.as_str())
                    .map(|name| self.pragma(schema, name, "index_info"))
            })
            .collect::<Vec<_>>();
        let details = if queries.is_empty() {
            Vec::new()
        } else {
            self.execute(queries.join(";\n")).await?
        };
        indexes
            .columns
            .extend(["columns".into(), "definition".into()]);
        for (index, row) in indexes.rows.iter_mut().enumerate() {
            let name = name_index.and_then(|i| row.get(i));
            let definition = definitions
                .rows
                .iter()
                .find(|r| r.first() == name)
                .and_then(|r| r.get(1));
            let names = details.get(index).map(|result| {
                result
                    .rows
                    .iter()
                    .map(|r| r.get(2).and_then(|v| v.as_str()).unwrap_or("<expression>"))
                    .collect::<Vec<_>>()
                    .join(", ")
            });
            row.push(names.map(serde_json::Value::from).unwrap_or_default());
            row.push(definition.cloned().unwrap_or_default());
        }
        Ok(indexes)
    }
}
